def list_items(path: Path) -> list[RegistryItem]:
    con = connect(path)
    try:
        rows = con.execute("SELECT * FROM vocab_registry ORDER BY id").fetchall()
        return [_item_from_row(row) for row in rows]
    finally:
        con.close()


